 const mrows=roleIds.map(r=>`<tr><td><b>${esc(L("role",r)||r)}</b> <span class="status num">${esc(r)}</span></td>${PERMS.map(([k])=>`<td style="text-align:center"><input type="checkbox" data-sp="roles.${esc(r)}.${k}" ${RR[r]?.[k]?"checked":""} aria-label="${esc(L("role",r)||r)} can ${k}"></td>`).join("")}</tr>`).join("");
