 const arows=Object.entries(A).sort((a,b)=>a[0].localeCompare(b[0])).map(([k,v])=>`<div class="litem"><div class="n fx"><input data-aliaskey="${esc(k)}" value="${esc(k)}" aria-label="Short word" placeholder="short" style="max-width:140px;font-family:var(--f-data)"><span class="status">→</span><input data-aliasval="${esc(k)}" value="${esc(v)}" aria-label="Expands to" placeholder="expands to"></div><button class="btn sm danger" data-act="delalias" data-k="${esc(k)}">Delete</button></div>`).join("");
