/* ---- legacy mapping ---- */
function legacyGroups(){const g={};[["purchases",D.purchases],["payments",D.payments],["shipments",D.shipments],["parties",D.parties]].forEach(([col,arr])=>live(arr).forEach(x=>Object.entries(x.legacy||{}).forEach(([f,v])=>{if(v==null||v==="")return;const k=col+"|"+f+"|"+String(v);g[k]=g[k]||{col,field:f,value:String(v),n:0,ids:[]};g[k].n++;if(g[k].ids.length<6)g[k].ids.push(x.no||x.id)})));return Object.values(g).sort((a,b)=>a.col.localeCompare(b.col)||a.field.localeCompare(b.field)||b.n-a.n)}
function legacyTargets(col,field){const lo=k=>items(k).map(i=>[i.id,i.label]);const cos=(SET().companies||[]).filter(c=>!c.archived).map(c=>[c.id,c.name]);switch(field){
 case"account":return cos;case"bank":return(SET().banks||[]).filter(b=>!b.archived).map(b=>[b.id,b.name+(b.cur?" · "+b.cur:"")]);case"deliverTo":return leafLocs();case"paidBy":return lo("paidBy");case"company":return cos.concat((SET().people||[]).filter(p=>!p.archived).map(p=>[p.id,p.name+" (person)"]));case"person":return(SET().people||[]).filter(p=>!p.archived).map(p=>[p.id,p.name]);case"platform":return lo("platform");case"mode":return lo("mode");case"goodsType":return lo("goodsType");case"incoterm":return lo("incoterm");case"originPort":return lo("originPort");case"terms":return lo("payTerms");case"country":return lo("country");case"cur":return items("currency").map(c=>[c.id,c.id]);case"kind":return lo("purchaseKind");case"refType":return lo("refType");case"dutyBy":return lo("dutyBy");case"email":return(SET().emails||[]).filter(e=>!e.archived).map(e=>[e.id,e.address]);
 case"type":return col==="payments"?lo("payType"):col==="parties"?lo("partyType"):lo("moveType");case"status":return col==="purchases"?lo("poStatus"):col==="shipments"?lo("shipStatus"):col==="payments"?lo("payStatus"):[["active","Active"],["archived","Archived"]];
 default:{const lk=Object.keys(SET().lists||{}).find(k=>k.toLowerCase()===field.toLowerCase());return lk?lo(lk):[]}}}
function sLegacy(){const gs=legacyGroups();if(!gs.length)return`<div class="card"><div class="okbox" style="margin:14px">All mapped ✓ — no legacy values left on purchases, payments, shipments or parties.</div></div>`;
 const rows=gs.map((g,i)=>{const t=legacyTargets(g.col,g.field);const sid=`leg_${i}`;return`<div class="litem"><div class="n fx" style="gap:8px"><span class="status" style="min-width:150px"><b>${esc(g.col)}</b> · ${esc(g.field)}</span><span class="num" style="min-width:120px" title="${esc(g.ids.join(", "))}">${esc(g.value)}</span><span class="status">${g.n} record${g.n===1?"":"s"} · ${g.ids.map(id=>`<button class="chipb" style="padding:1px 6px;font-size:11px" data-open="${esc(g.col)}" data-id="${esc(id)}">${esc(id)}</button>`).join(" ")}${g.n>g.ids.length?" …":""}</span><span class="status">→</span>${t.length?`<select data-legacysel="${sid}" aria-label="Map to"><option value="">— pick the right value —</option>${optsHtml(t,"")}</select>`:`<span class="warnbox">No list for "${esc(g.field)}" — add items under Lists first</span>`}</div><button class="btn sm pri" data-act="maplegacy" data-col="${esc(g.col)}" data-field="${esc(g.field)}" data-value="${esc(g.value)}" data-sel="${sid}" ${t.length?"":"disabled"}>Map all</button></div>`}).join("");
 return fsec(`Legacy values to map (${gs.length})`,rows)+`<p class="note">These came from the old sheets and did not match a Setup item. Choose the right item and "Map all" updates every record with that value in one undoable step and clears the legacy note. New items can be added under Dropdown lists, Companies, Banks or Locations first.</p>`}
/* ---- backup ---- */
function sBackup(){const s=SET();const n=k=>Object.keys(s.lists||{}).length;return fsec("Backup & restore",`<div style="padding:14px;display:flex;flex-direction:column;gap:12px">
 <div class="status">Setup: ${(s.companies||[]).length} companies · ${(s.banks||[]).length} banks · ${(s.locations||[]).length} locations · ${n()} lists · ${Object.keys(s.forms||{}).length} customised forms · updated ${esc(s.updatedAt?fmtD(s.updatedAt.slice(0,10)):"—")}</div>
 <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" data-act="exportsetup">Export Setup (JSON)</button><button class="btn" data-act="exportall">Export everything (JSON)</button><button class="btn" data-act="exportxlsx" data-scope="all">Export everything (Excel)</button></div>
 <label class="dz" style="display:block">Restore Setup from a JSON file exported here<br><small class="status">Replaces the whole Setup document (lists, numbering, forms, defaults, users). Records are not touched. Undoable.</small><input id="setup_file" type="file" accept=".json,application/json" data-act="importsetup" hidden></label><div id="setup_import_out"></div>
 <p class="note">In the real build a nightly copy of Setup and all records goes to the Drive folder "${esc(s.driveRoot||"NEXUS")}/Backups". Here, use the buttons above before big changes.</p></div>`)}
function exportSetupJson(){const d=JSON.parse(JSON.stringify(SET()));const blob=new Blob([JSON.stringify(d,null,1)],{type:"application/json"});return saveBlob(blob,`NEXUS_setup_${today()}.json`)}
function exportAllJson(){if(!can("export")){toast("Export is not allowed for your role");return}const out={exportedAt:nowIso(),setup:SET(),counters:D.counters};COLS.forEach(c=>{out[c]=(D[c]||[]).map(x=>can("bank")?x:stripBank(c,x))});const blob=new Blob([JSON.stringify(out)],{type:"application/json"});return saveBlob(blob,`NEXUS_all_${today()}.json`)}
function stripBank(col,x){if(can("bank"))return x;const y={...x};["bank","beneficiary","email","defaultBank","bankFeeGbp","last4"].forEach(k=>{if(k in y)delete y[k]});return y}
async function importSetupJson(file){if(!file)return;let d;try{d=JSON.parse(await file.text())}catch(e){toast("Not a JSON file");return}if(!d||typeof d!=="object"||!d.lists||typeof d.lists!=="object"){toast("This file has no Setup lists — not a Setup export");return}
 S.pendingSetup=d;const out=$("#setup_import_out");const sum=`${Object.keys(d.lists).length} lists · ${(d.companies||[]).length} companies · ${(d.banks||[]).length} banks · ${(d.locations||[]).length} locations · ${(d.users||[]).length} users${d.updatedAt?" · saved "+fmtD(d.updatedAt.slice(0,10)):""}`;
 if(out)out.innerHTML=`<div class="warnbox" style="margin-top:10px">Replace the current Setup with <b>${esc(file.name)}</b>? (${esc(sum)}) <div style="margin-top:6px;display:flex;gap:6px"><button class="btn sm pri" data-act="confirmsetup">Yes, replace Setup</button><button class="btn sm" data-act="cancelsetup">Cancel</button></div></div>`;else toast("Loaded "+sum)}
async function confirmSetupImport(){const d=S.pendingSetup;if(!d){toast("Nothing to import");return}const before=JSON.parse(JSON.stringify(D.setup||{}));const next={...d,id:"main",updatedAt:nowIso()};try{await db.collection("setup").doc("main").set(next);D.setup=next;pushUndo({label:"Setup restored from file",col:"setup",id:"main",before,after:next});S.pendingSetup=null;toast("Setup replaced from file",{undo:true});render()}catch(e){console.error(e);toast("Could not save Setup")}}

