function withCustom(col,fn){const form=XFORM[col];const cf=form?fields(form).filter(f=>f.custom):[];if(!cf.length)return fn;return x=>{const o=fn(x);cf.forEach(f=>{const v=x?.custom?.[f.k];o[f.l||f.k]=v==null?"":(typeof customVal==="function"?customVal(f,v)??v:v)});return o}}
